// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (e.g. 200 for unknown orders). Change expectations only deliberately.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 2.5, gold: 101, hundred: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order and returns 201 with JSON', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.deepEqual(order, { id: order.id, items: [{ sku: 'apple', qty: 2 }], total: 20 })
  assert.match(order.id, /^\d+$/)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(typeof a.id, 'string')
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items', async () => {
  const o = await (await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 2 }] })).json()
  assert.equal(o.total, 15)
})

test('total is floored to a whole number', async () => {
  const o = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(o.total, 2)
})

test('no discount at exactly 100', async () => {
  const o = await (await post({ items: [{ sku: 'hundred', qty: 1 }] })).json()
  assert.equal(o.total, 100)
})

test('10% discount applies above 100, then floors', async () => {
  const o = await (await post({ items: [{ sku: 'gold', qty: 1 }] })).json()
  assert.equal(o.total, 90) // 101 * 0.9 = 90.9
  const p = await (await post({ items: [{ sku: 'apple', qty: 20 }] })).json()
  assert.equal(p.total, 180)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'apple', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['malformed JSON', null, '{not json'],
  ['empty body', null, ''],
]) {
  test(`POST /orders rejects ${name} with 400`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('rejected requests do not consume an id', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  await post({ items: [] })
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('unknown routes and methods return 404 "no route"', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/extra']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 1 }] })
  const { id } = await res.json()
  const got = await fetch(`${base}/orders/${id}?x=1`)
  assert.equal((await got.json()).id, id)
})
